public String exchangePasswordForToken(String username, String password) {
    RestTemplate restTemplate = new RestTemplate();
    String tokenUrl = "https://auth.enterprise.internal/oauth/token";

    MultiValueMap<String, String> requestBody = new LinkedMultiValueMap<>();
    requestBody.add("grant_type", "password");
    requestBody.add("client_id", "legacy-native-app");
    requestBody.add("client_secret", "secure-secret");
    requestBody.add("username", username);
    requestBody.add("password", password);

    HttpHeaders headers = new HttpHeaders();
    headers.setContentType(MediaType.APPLICATION_FORM_URLENCODED);

    HttpEntity<MultiValueMap<String, String>> request = new HttpEntity<>(requestBody, headers);

    // ANTI-PATTERN: Passing raw credentials through application layers
    ResponseEntity<OAuthResponse> response = restTemplate.postForEntity(tokenUrl, request, OAuthResponse.class);
    return response.getBody().getAccessToken();
}
